97	TEST_F(XdsOverrideHostTest, OverrideHost) {
98	  // Send address list to LB policy.
99	  const std::array<absl::string_view, 3> kAddresses = {
100	      "ipv4:127.0.0.1:441", "ipv4:127.0.0.1:442", "ipv4:127.0.0.1:443"};
101	  auto picker = ExpectStartupWithRoundRobin(kAddresses);
102	  ASSERT_NE(picker, nullptr);
103	  // Check that the host is overridden
104	  std::map<UniqueTypeName, std::string> call_attributes{
105	      {XdsHostOverrideTypeName(), "127.0.0.1:442"}};
106	  EXPECT_EQ(ExpectPickComplete(picker.get(), call_attributes), kAddresses[1]);
107	  EXPECT_EQ(ExpectPickComplete(picker.get(), call_attributes), kAddresses[1]);
108	  call_attributes[XdsHostOverrideTypeName()] = std::string("127.0.0.1:441");
109	  EXPECT_EQ(ExpectPickComplete(picker.get(), call_attributes), kAddresses[0]);
110	  EXPECT_EQ(ExpectPickComplete(picker.get(), call_attributes), kAddresses[0]);
111	}
112	
113	TEST_F(XdsOverrideHostTest, OverrideHostSubchannelNotFound) {
114	  // Send address list to LB policy.
115	  const std::array<absl::string_view, 3> kAddresses = {
116	      "ipv4:127.0.0.1:441", "ipv4:127.0.0.1:442", "ipv4:127.0.0.1:443"};
117	  auto picker = ExpectStartupWithRoundRobin(kAddresses);
118	  ASSERT_NE(picker, nullptr);
119	  std::map<UniqueTypeName, std::string> call_attributes{
120	      {XdsHostOverrideTypeName(), "no such host"}};
121	  ExpectRoundRobinPicks(picker.get(), kAddresses, call_attributes);
122	}
123	
124	TEST_F(XdsOverrideHostTest, SubchannelsComeAndGo) {
125	  const std::array<absl::string_view, 3> kAddresses = {
126	      "ipv4:127.0.0.1:441", "ipv4:127.0.0.1:442", "ipv4:127.0.0.1:443"};
127	  auto picker = ExpectStartupWithRoundRobin(kAddresses);
128	  ASSERT_NE(picker, nullptr);
129	  // Check that the host is overridden
130	  std::map<UniqueTypeName, std::string> call_attributes{
131	      {XdsHostOverrideTypeName(), "127.0.0.1:442"}};
132	  ExpectRoundRobinPicks(picker.get(), {kAddresses[1]}, call_attributes);
133	  // Some other address is gone
134	  EXPECT_EQ(ApplyUpdate(BuildUpdate({kAddresses[0], kAddresses[1]},
135	                                    MakeXdsOverrideHostConfig()),
136	                        policy_.get()),
137	            absl::OkStatus());
138	  // Wait for LB policy to return a new picker that uses the updated
139	  // addresses.  We can't use the host override for this, because then
140	  // we won't know when the new picker is actually using all of the new
141	  // addresses.
142	  picker =
143	      WaitForRoundRobinListChange(kAddresses, {kAddresses[0], kAddresses[1]});
144	  // Make sure host override still works.
145	  ExpectRoundRobinPicks(picker.get(), {kAddresses[1]}, call_attributes);
146	  // "Our" address is gone so others get returned in round-robin order
147	  EXPECT_EQ(ApplyUpdate(BuildUpdate({kAddresses[0], kAddresses[2]},
148	                                    MakeXdsOverrideHostConfig()),
149	                        policy_.get()),
150	            absl::OkStatus());
151	  // Wait for LB policy to return the new picker.
152	  // In this case, we can pass call_attributes while we wait instead of
153	  // checking again afterward, because the host override won't actually
154	  // be used.
155	  WaitForRoundRobinListChange({kAddresses[0], kAddresses[1]},
156	                              {kAddresses[0], kAddresses[2]}, call_attributes);
157	  // And now it is back
158	  EXPECT_EQ(ApplyUpdate(BuildUpdate({kAddresses[1], kAddresses[2]},
159	                                    MakeXdsOverrideHostConfig()),
160	                        policy_.get()),
161	            absl::OkStatus());
162	  // Wait for LB policy to return the new picker.
163	  picker = WaitForRoundRobinListChange({kAddresses[0], kAddresses[2]},
164	                                       {kAddresses[1], kAddresses[2]});
165	  // Make sure host override works.
166	  ExpectRoundRobinPicks(picker.get(), {kAddresses[1]}, call_attributes);
167	}
