60	LoadBalancingPolicy::PickResult LoadBalancingPolicy::QueuePicker::Pick(
61	    PickArgs /*args*/) {
62	  // We invoke the parent's ExitIdleLocked() via a closure instead
63	  // of doing it directly here, for two reasons:
64	  // 1. ExitIdleLocked() may cause the policy's state to change and
65	  //    a new picker to be delivered to the channel.  If that new
66	  //    picker is delivered before ExitIdleLocked() returns, then by
67	  //    the time this function returns, the pick will already have
68	  //    been processed, and we'll be trying to re-process the same
69	  //    pick again, leading to a crash.
70	  // 2. We are currently running in the data plane mutex, but we
71	  //    need to bounce into the control plane work_serializer to call
72	  //    ExitIdleLocked().
73	  if (!exit_idle_called_ && parent_ != nullptr) {
74	    exit_idle_called_ = true;
75	    auto* parent = parent_->Ref().release();  // ref held by lambda.
76	    ExecCtx::Run(DEBUG_LOCATION,
77	                 GRPC_CLOSURE_CREATE(
78	                     [](void* arg, grpc_error_handle /*error*/) {
79	                       auto* parent = static_cast<LoadBalancingPolicy*>(arg);
80	                       parent->work_serializer()->Run(
81	                           [parent]() {
82	                             parent->ExitIdleLocked();
83	                             parent->Unref();
84	                           },
85	                           DEBUG_LOCATION);
86	                     },
87	                     parent, nullptr),
88	                 absl::OkStatus());
89	  }
