void XdsOverrideHostLb::SubchannelWrapper::WatchConnectivityState(
    std::unique_ptr<ConnectivityStateWatcherInterface> watcher) {
  auto& watcher_wrapper = watchers_[watcher.get()];
  GPR_ASSERT(watcher_wrapper == nullptr);
  auto wrapper = std::make_unique<WatcherWrapper>(std::move(watcher), this);
  watcher_wrapper = wrapper.get();
  wrapped_subchannel()->WatchConnectivityState(std::move(wrapper));
}

void XdsOverrideHostLb::SubchannelWrapper::CancelConnectivityStateWatch(
    ConnectivityStateWatcherInterface* watcher) {
  auto it = watchers_.find(watcher);
  if (it == watchers_.end()) return;
  wrapped_subchannel()->CancelConnectivityStateWatch(it->second);
  watchers_.erase(it);
}

void XdsOverrideHostLb::SubchannelWrapper::UpdateConnectivityState(
    grpc_connectivity_state state) {
  grpc_connectivity_state previous_state =
      connectivity_state_.exchange(state, std::memory_order_relaxed);
  // When a tracked override-host subchannel transitions to IDLE or
  // TRANSIENT_FAILURE, ask the channel to re-resolve so that we get a fresh
  // set of addresses.  We only do this on an actual state transition, to
  // avoid spuriously requesting re-resolution when the initial state is
  // first reported.
  if (key_.has_value() && state != previous_state &&
      (state == GRPC_CHANNEL_IDLE ||
       state == GRPC_CHANNEL_TRANSIENT_FAILURE)) {
    if (!policy_->shutting_down_) {
      policy_->channel_control_helper()->RequestReresolution();
    }
  }
