607	void XdsOverrideHostLb::SubchannelWrapper::UpdateConnectivityState(
608	    grpc_connectivity_state state) {
609	  grpc_connectivity_state previous_state =
610	      connectivity_state_.exchange(state, std::memory_order_relaxed);
611	  // When a tracked override-host subchannel transitions to IDLE or
612	  // TRANSIENT_FAILURE, ask the channel to re-resolve so that we get a fresh
613	  // set of addresses.  We only do this on an actual state transition, to
614	  // avoid spuriously requesting re-resolution when the initial state is
615	  // first reported.
616	  if (key_.has_value() && state != previous_state &&
617	      (state == GRPC_CHANNEL_IDLE ||
618	       state == GRPC_CHANNEL_TRANSIENT_FAILURE)) {
619	    if (!policy_->shutting_down_) {
620	      policy_->channel_control_helper()->RequestReresolution();
621	    }
622	  }
623	}
